// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OtpInvites) predicate.OtpInvites {
	return predicate.OtpInvites(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OtpInvites) predicate.OtpInvites {
	return predicate.OtpInvites(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OtpInvites) predicate.OtpInvites {
	return predicate.OtpInvites(sql.NotPredicates(p))
}
